//! The Compose file Dock generates from `dock.toml` and hands to
//! `docker compose` or `podman compose`. Nobody edits it: it is rewritten
//! each time Dock runs Compose (`up`, and `down` without service names),
//! under `.navree/dock/` (which ignores itself in git).

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use crate::config::DockFile;
use crate::error::DockError;
use crate::service::{HOST, ServiceSpec};

/// The generated file, relative to the app's directory.
pub const COMPOSE_FILE: &str = ".navree/dock/compose.yaml";

/// The label every container and volume carries, with the project as its value.
pub const PROJECT_LABEL: &str = "dev.navree.dock.project";

/// The label naming a container's service.
pub const SERVICE_LABEL: &str = "dev.navree.dock.service";

/// The Compose file for `file`: one service per entry, with its container
/// name, labels, environment, command, ports on 127.0.0.1 and named volume.
pub fn render(file: &DockFile) -> String {
    let mut out = String::new();
    out.push_str("# Generated by `navree dock` from dock.toml. Edit dock.toml instead.\n");
    let _ = writeln!(out, "name: {}", quote(&file.project));
    if file.services.is_empty() {
        out.push_str("services: {}\n");
        return out;
    }
    out.push_str("services:\n");
    for spec in &file.services {
        render_service(&mut out, &file.project, spec);
    }
    out.push_str("volumes:\n");
    for spec in &file.services {
        let _ = writeln!(out, "  {}:", spec.volume);
        let _ = writeln!(out, "    name: {}", quote(&spec.volume));
        out.push_str("    labels:\n");
        let _ = writeln!(out, "      {PROJECT_LABEL}: {}", quote(&file.project));
    }
    out
}

fn render_service(out: &mut String, project: &str, spec: &ServiceSpec) {
    let _ = writeln!(out, "  {}:", spec.name());
    let _ = writeln!(out, "    image: {}", quote(&spec.image));
    let _ = writeln!(out, "    container_name: {}", quote(&spec.container));
    out.push_str("    labels:\n");
    let _ = writeln!(out, "      {PROJECT_LABEL}: {}", quote(project));
    let _ = writeln!(out, "      {SERVICE_LABEL}: {}", quote(spec.name()));
    let env = spec.container_env();
    if !env.is_empty() {
        out.push_str("    environment:\n");
        for (name, value) in env {
            let _ = writeln!(out, "      {name}: {}", quote(&value));
        }
    }
    if let Some(command) = spec.command() {
        let words: Vec<String> = command.iter().map(|w| quote(w)).collect();
        let _ = writeln!(out, "    command: [{}]", words.join(", "));
    }
    out.push_str("    ports:\n");
    for port in &spec.ports {
        let _ = writeln!(
            out,
            "      - {}",
            quote(&format!("{HOST}:{}:{}", port.host, port.container))
        );
    }
    out.push_str("    volumes:\n");
    let _ = writeln!(
        out,
        "      - {}",
        quote(&format!("{}:{}", spec.volume, spec.data_path()))
    );
}

/// A YAML double-quoted scalar (JSON string syntax, which YAML accepts),
/// with `$` doubled so Compose does not interpolate it.
fn quote(value: &str) -> String {
    serde_json::to_string(&value.replace('$', "$$")).unwrap_or_else(|_| "\"\"".to_owned())
}

/// Writes the Compose file for `file` under `root`, and a `.gitignore` that
/// keeps `.navree/` out of git. Returns the path written.
pub fn write(root: &Path, file: &DockFile) -> Result<PathBuf, DockError> {
    let path = root.join(COMPOSE_FILE);
    let dir = path.parent().unwrap_or(root);
    std::fs::create_dir_all(dir).map_err(|e| DockError::io(dir, e))?;
    let ignore = root.join(".navree").join(".gitignore");
    if !ignore.exists() {
        std::fs::write(
            &ignore,
            "# Written by navree; nothing here belongs in git.\n*\n",
        )
        .map_err(|e| DockError::io(&ignore, e))?;
    }
    std::fs::write(&path, render(file)).map_err(|e| DockError::io(&path, e))?;
    Ok(path)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn values_are_quoted_and_dollars_escaped() {
        assert_eq!(quote("postgres:17"), "\"postgres:17\"");
        assert_eq!(quote("a\"b"), r#""a\"b""#);
        assert_eq!(quote("pa$word"), "\"pa$$word\"");
    }

    #[test]
    fn a_file_without_services_is_still_valid() {
        let file = DockFile::parse("project = \"empty\"\n", "empty").unwrap();
        assert_eq!(
            render(&file),
            "# Generated by `navree dock` from dock.toml. Edit dock.toml instead.\nname: \"empty\"\nservices: {}\n"
        );
    }

    #[test]
    fn write_creates_the_file_and_a_self_ignoring_directory() {
        let dir = tempfile::Builder::new()
            .prefix("navree-test-")
            .tempdir()
            .unwrap();
        let file = DockFile::parse("[services.redis]\n", "shop").unwrap();
        let path = write(dir.path(), &file).unwrap();
        assert_eq!(path, dir.path().join(COMPOSE_FILE));
        assert_eq!(std::fs::read_to_string(&path).unwrap(), render(&file));
        let ignore = std::fs::read_to_string(dir.path().join(".navree/.gitignore")).unwrap();
        assert!(ignore.lines().any(|line| line == "*"), "{ignore}");
    }
}
